CREATE TABLE financial_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,name text NOT NULL,account_type text NOT NULL CHECK(account_type IN('cash','bank','wallet')),currency text NOT NULL DEFAULT 'EGP',balance numeric(18,2) NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,name));
CREATE TABLE financial_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,account_id uuid NOT NULL REFERENCES financial_accounts(id) ON DELETE RESTRICT,movement_type text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount<>0),business_date date NOT NULL,description text NOT NULL,source_type text NOT NULL,source_id uuid NOT NULL,operation_key text,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,source_type,source_id,account_id,movement_type));
CREATE TABLE financial_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,transfer_number text NOT NULL,from_account_id uuid NOT NULL REFERENCES financial_accounts(id),to_account_id uuid NOT NULL REFERENCES financial_accounts(id),amount numeric(18,2) NOT NULL CHECK(amount>0),business_date date NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'posted',operation_key text,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(from_account_id<>to_account_id),UNIQUE(company_id,transfer_number));
CREATE TABLE reconciliations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,account_id uuid NOT NULL REFERENCES financial_accounts(id),statement_reference text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,closing_balance numeric(18,2) NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','completed')),completed_at timestamptz,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,account_id,statement_reference));
CREATE TABLE reconciliation_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reconciliation_id uuid NOT NULL REFERENCES reconciliations(id) ON DELETE RESTRICT,external_id text NOT NULL,business_date date NOT NULL,description text NOT NULL,amount numeric(18,2) NOT NULL,matched_movement_id uuid REFERENCES financial_movements(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(reconciliation_id,external_id));
ALTER TABLE expenses ADD COLUMN IF NOT EXISTS submitted_by uuid REFERENCES users(id),ADD COLUMN IF NOT EXISTS approved_by uuid REFERENCES users(id),ADD COLUMN IF NOT EXISTS paid_by uuid REFERENCES users(id),ADD COLUMN IF NOT EXISTS financial_account_id uuid REFERENCES financial_accounts(id),ADD COLUMN IF NOT EXISTS operation_key text;
CREATE INDEX idx_financial_movements_account_date ON financial_movements(account_id,business_date DESC);CREATE INDEX idx_reconciliation_lines_parent ON reconciliation_lines(reconciliation_id);
